import logging

logging.basicConfig(level=logging.ERROR, format='%(levelname)s - %(message)s')

def divide(a, b):
    return a / b

try:
    divide(10, 0)
except ZeroDivisionError:
    logging.exception('Division failed')

print('Program continues after logging the error')

